        const items = Array.from(root.current?.querySelectorAll<HTMLElement>("button:not([disabled]), a[href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex='0']") ?? []).filter(el => el.offsetParent !== null);
