  function move(e: PointerEvent<SVGSVGElement>) { const d = drag.current; if (!d) return; const rect = graph.current?.getBoundingClientRect(); const factor = rect ? 950 / rect.width : 1; const dx = (e.clientX - d.x) * factor, dy = (e.clientY - d.y) * factor; if (d.id) setPositions(p => ({ ...p, [d.id!]: { x: d.ox + dx / zoom, y: d.oy + dy / zoom } })); else setPan({ x: d.ox + dx, y: d.oy + dy }); }
  const points = Object.values(positions);
  const bounds = { x: Math.min(0, ...points.map(p => p.x)) - 20, y: Math.min(0, ...points.map(p => p.y)) - 20, right: Math.max(214, ...points.map(p => p.x + 214)) + 20, bottom: Math.max(104, ...points.map(p => p.y + 104)) + 20 };
  const boundsWidth = bounds.right - bounds.x, boundsHeight = bounds.bottom - bounds.y;
  function fit() { const z = Math.min(1.5, 910 / boundsWidth, 520 / boundsHeight); setZoom(z); setPan({ x: (950 - boundsWidth * z) / 2 - bounds.x * z, y: (560 - boundsHeight * z) / 2 - bounds.y * z }); }
  const edges = [...bp.relationships.map(r => ({ ...r, manual: false })), ...manual.map(r => ({ ...r, keys: [], cardinality: "exploratory", manual: true }))];
  return <div className="map-view"><div className="map-toolbar"><div><h2>Source relationships</h2><p className="muted small">Drag nodes to arrange. Drag the background to pan. Select a table for details.</p></div><div className="button-row"><button className="icon-button" aria-label="Zoom out" onClick={() => setZoom(z => Math.max(0.25, z - .15))}><Minus size={17} /></button><span className="zoom-label">{Math.round(zoom * 100)}%</span><button className="icon-button" aria-label="Zoom in" onClick={() => setZoom(z => Math.min(2, z + .15))}><Plus size={17} /></button><button className="button button-small" onClick={fit}><Maximize2 size={14} />Fit all</button><button className="button button-small" onClick={() => { setZoom(.85); setPan({ x: 0, y: 0 }); setPositions(initial); }}><Maximize2 size={14} />Reset view</button></div></div><div className="graph-canvas"><svg ref={graph} className="graph-svg" viewBox="0 0 950 560" role="img" aria-label="Interactive table relationship diagram" onPointerDown={e => down(e, null)} onPointerMove={move} onPointerUp={() => { drag.current = null; }} onPointerCancel={() => { drag.current = null; }}><defs><pattern id="dots" x="0" y="0" width="22" height="22" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="#243044" /></pattern><marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#8b7bc1" /></marker></defs><rect width="100%" height="100%" fill="url(#dots)" /><g transform={`translate(${pan.x} ${pan.y}) scale(${zoom})`}>{edges.map((r, i) => { const a = positions[r.from], b = positions[r.to]; if (!a || !b) return null; return <g key={i} className={r.manual ? "manual-edge" : ""}><path d={`M ${a.x + 214} ${a.y + 48} C ${a.x + 260} ${a.y + 48}, ${b.x - 45} ${b.y + 48}, ${b.x} ${b.y + 48}`} fill="none" stroke={r.manual ? "#d5a858" : "#8b7bc1"} strokeWidth="1.7" markerEnd="url(#arrow)" /><text x={(a.x + b.x + 214) / 2} y={(a.y + b.y) / 2 + 38} className="edge-text">{r.cardinality}</text></g>; })}{bp.tables.map(t => { const p = positions[t.id]; if (!p) return null; return <g key={t.id} transform={`translate(${p.x} ${p.y})`} className="graph-node" tabIndex={0} role="button" aria-label={`View ${t.id} details`} onPointerDown={e => down(e, t.id)} onClick={() => select(t)} onKeyDown={e => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); select(t); } }}><rect width="214" height="104" rx="10" fill={t.custom ? "#302717" : "#172539"} stroke={t.custom ? "#ad8438" : "#4565a1"} /><text x="16" y="22" className="node-category">{t.custom ? "CUSTOM" : t.system} · {t.module}</text><text x="16" y="48" className="node-title">{t.id}</text><text x="16" y="69" className="node-description">{t.name.length > 27 ? t.name.slice(0, 27) + "…" : t.name}</text><text x="16" y="90" className="node-fields">{t.fields.length} fields · {t.fields.filter(f => f.isKey).length} keys</text><circle cx="0" cy="48" r="4" fill="#9f8ec9" /><circle cx="214" cy="48" r="4" fill="#9f8ec9" /></g>; })}</g></svg><div className="graph-minimap" aria-label="Table map overview"><span>OVERVIEW</span><svg viewBox={`${bounds.x} ${bounds.y} ${boundsWidth} ${boundsHeight}`} role="img" aria-label="Overview of all table positions">{bp.tables.map(t => positions[t.id] && <rect key={t.id} x={positions[t.id].x} y={positions[t.id].y} width="214" height="104" rx="8" fill={t.custom ? "#b69354" : "#718bb2"} />)}<rect x={-pan.x / zoom} y={-pan.y / zoom} width={950 / zoom} height={560 / zoom} fill="#bda0e515" stroke="#bda0e5" strokeWidth={Math.max(boundsWidth / 150, 2)} /></svg></div></div><div className="map-bottom"><div className="map-legend"><span><i className="legend-dot" />Catalog relationship</span><span><i className="legend-dot amber" />Exploratory edge</span></div><details className="manual-connect"><summary><Link2 size={14} />Explore a relationship</summary><p className="muted small">Temporary visual connection only. Does not change SQL, saved data, or verified joins.</p><div className="button-row"><select aria-label="Connect from table" value={from} onChange={e => setFrom(e.target.value)}><option value="">From table</option>{bp.tables.map(t => <option key={t.id}>{t.id}</option>)}</select><ArrowRight size={14} /><select aria-label="Connect to table" value={to} onChange={e => setTo(e.target.value)}><option value="">To table</option>{bp.tables.map(t => <option key={t.id}>{t.id}</option>)}</select><button className="button button-small" disabled={!from || !to || from === to || manual.some(r => r.from === from && r.to === to)} onClick={() => setManual([...manual, { from, to }])}>Connect</button>{manual.length > 0 && <button className="text-button" onClick={() => setManual([])}>Clear</button>}</div></details></div><div className="relationship-list"><h3>Join specifications</h3>{bp.relationships.length ? <div className="table-wrap"><table><thead><tr><th>From → To</th><th>Join conditions</th><th>Cardinality</th></tr></thead><tbody>{bp.relationships.map((r, i) => <tr key={i}><td><code>{r.from} → {r.to}</code></td><td>{r.keys.join(" AND ")}</td><td>{r.cardinality}</td></tr>)}</tbody></table></div> : <p className="muted">No validated catalog relationship is available for this selection. Do not infer a join from matching field names.</p>}</div></div>;
